  "content": "1|import {
2|  isPublicFunctionAccessControl,
3|  parseFunctionAccessControl,
4|  type FunctionAccessControl,
5|} from '../../shared/api/contracts/server-functions/accessControl';
6|import { listManagedFunctionRouteRows } from '../domain/functions/functionRepository';
7|import type { ManagedFunctionExecutionRecord } from './server-function.service';
8|
9|export type ManagedFunctionRouteMatch = {
10|  function: ManagedFunctionExecutionRecord;
11|  params: Record<string, string>;
12|};
13|
14|type ManagedFunctionRouteEntry = ManagedFunctionExecutionRecord & {
15|  pathRegex: RegExp;
16|  paramNames: string[];
17|  isDirectSql: boolean;
18|  isMultiMethod: boolean;
19|};
20|
21|const isBundledAutoCrudOrigin = (metadataJson: Record<string, unknown> | null | undefined): boolean => (
22|  metadataJson?.origin === 'auto-crud'
23|);
24|
25|const RESERVED_API_PREFIXES = [
26|  '/api/auth',
27|  '/api/users',
28|  '/api/roles',
29|  '/api/functions',
30|  '/api/data-sources',
31|  '/api/core',
32|  '/api/packages',
33|  '/api/cache',
34|  '/api/git',
35|  '/api/logs',
36|  '/api/settings',
37|  '/api/profile',
38|  '/api/base-info',
39|  '/api/health',
40|  '/api/project-standards',
41|  '/api/ai',
42|  '/api/component-designer',
43|  '/api/docs',
44|  '/api/mcp',
45|];
46|
47|const normalizeRequestPath = (path: string): string => {
48|  const withoutQuery = path.split('?')[0] || '/';
49|  if (withoutQuery.length > 1 && withoutQuery.endsWith('/')) {
50|    return withoutQuery.slice(0, -1);
51|  }
52|  return withoutQuery;
53|};
54|
55|const escapeRegex = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
56|
57|const compileRoutePattern = (routePath: string): { pathRegex: RegExp; paramNames: string[] } => {
58|  const normalizedPath = normalizeRequestPath(routePath);
59|  const segments = normalizedPath.split('/').filter(Boolean);
60|  const paramNames: string[] = [];
61|
62|  const regexBody = segments.map((segment) => {
63|    if (segment.startsWith(':')) {
64|      paramNames.push(segment.slice(1));
65|      return '([^/]+)';
66|    }
67|    return escapeRegex(segment);
68|  }).join('/');
69|
70|  return {
71|    pathRegex: new RegExp(`^/${regexBody}/?$`),
72|    paramNames,
73|  };
74|};
75|
76|const toManagedFunctionRecord = (row: Record<string, unknown>): ManagedFunctionExecutionRecord => ({
77|  id: String(row.id || ''),
78|  name: String(row.name || ''),
79|  folder: String(row.folder || ''),
80|  method: String(row.method || 'GET'),
81|  path: String(row.path || ''),
82|  code: String(row.code || ''),
83|  language: typeof row.language === 'string' ? row.language : undefined,
84|  test_payload: row.test_payload,
85|  testPayload: typeof row.test_payload === 'string' ? row.test_payload : undefined,
86|  runtime_version: typeof row.runtime_version === 'string' ? row.runtime_version : undefined,
87|  runtimeVersion: typeof row.runtime_version === 'string' ? row.runtime_version : undefined,
88|  memory_limit: typeof row.memory_limit === 'number' ? row.memory_limit : undefined,
89|  memoryLimit: typeof row.memory_limit === 'number' ? row.memory_limit : undefined,
90|  use_global_config: row.use_global_config !== false,
91|  useGlobalConfig: row.use_global_config !== false,
92|  enable_logs: typeof row.enable_logs === 'boolean' ? row.enable_logs : undefined,
93|  enableLogs: typeof row.enable_logs === 'boolean' ? row.enable_logs : undefined,
94|  timeout_ms: typeof row.timeout_ms === 'number' ? row.timeout_ms : undefined,
95|  timeoutMs: typeof row.timeout_ms === 'number' ? row.timeout_ms : undefined,
96|  cache_enabled: row.cache_enabled === true,
97|  cacheEnabled: row.cache_enabled === true,
98|  cache_ttl_ms: typeof row.cache_ttl_ms === 'number' ? row.cache_ttl_ms : undefined,
99|  cacheTtlMs: typeof row.cache_ttl_ms === 'number' ? row.cache_ttl_ms : undefined,
100|  cache_by_param: row.cache_by_param === true,
101|  cacheByParam: row.cache_by_param === true,
102|  cache_by_user: row.cache_by_user === true,
103|  cacheByUser: row.cache_by_user === true,
104|  engine_type: row.engine_type === 'DIRECT_SQL' ? 'DIRECT_SQL' : 'SANDBOX_JS',
105|  engineType: row.engine_type === 'DIRECT_SQL' ? 'DIRECT_SQL' : 'SANDBOX_JS',
106|  metadata_json: typeof row.metadata_json === 'string'
107|    ? row.metadata_json
108|    : (row.metadata_json === null || row.metadata_json === undefined
109|      ? null
110|      : JSON.stringify(row.metadata_json)),
111|  metadataJson: typeof row.metadata_json === 'string'
112|    ? (row.metadata_json ? JSON.parse(row.metadata_json) as Record<string, unknown> : null)
113|    : ((row.metadata_json as Record<string, unknown> | null | undefined) ?? null),
114|  access_control: parseFunctionAccessControl(row.access_control ?? row.accessControl),
115|  accessControl: parseFunctionAccessControl(row.access_control ?? row.accessControl),
116|});
117|
118|const resolveEntryAccessControl = (entry: ManagedFunctionRouteEntry): FunctionAccessControl => (
119|  parseFunctionAccessControl(entry.access_control ?? entry.accessControl)
120|);
